        /* Dashboard Metrics CSS */
.dashboard {
  max-width: 1200px;
  margin: 0 auto;
  padding: 20px;
}

.dashboard-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
  gap: 20px;
  margin-bottom: 30px;
}

.metric-card {
  background: rgba(255, 255, 255, 0.1);
  backdrop-filter: blur(10px);
  border-radius: 16px;
  padding: 20px;
  border: 1px solid rgba(255, 255, 255, 0.1);
  position: relative;
  overflow: hidden;
  transition: all 0.3s ease;
}

.metric-card:hover {
  transform: translateY(-5px);
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.1);
  border-color: rgba(255, 255, 255, 0.2);
}

.metric-card.primary { border-left: 4px solid #3b82f6; }
.metric-card.success { border-left: 4px solid #10b981; }
.metric-card.warning { border-left: 4px solid #f59e0b; }
.metric-card.info { border-left: 4px solid #8b5cf6; }

.metric-icon {
  font-size: 2.5rem;
  margin-bottom: 15px;
  display: block;
}

.metric-content h3 {
  color: rgba(255, 255, 255, 0.8);
  font-size: 0.9rem;
  font-weight: 500;
  margin: 0 0 8px 0;
  text-transform: uppercase;
  letter-spacing: 1px;
}

.metric-value {
  font-size: 2.5rem;
  font-weight: 700;
  color: white;
  margin: 10px 0;
  line-height: 1;
}

.metric-subtitle {
  color: rgba(255, 255, 255, 0.6);
  font-size: 0.8rem;
  margin-top: 5px;
}

/* Circular Progress */
.metric-progress {
  position: absolute;
  top: 20px;
  right: 20px;
}

.circular-progress {
  position: relative;
  width: 60px;
  height: 60px;
}

.circular-progress svg {
  width: 100%;
  height: 100%;
  transform: rotate(-90deg);
}

.circular-progress circle {
  transition: stroke-dasharray 0.5s ease;
}

.progress-text {
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  font-size: 0.8rem;
  font-weight: 600;
  color: white;
}

/* Responsive */
@media (max-width: 768px) {
  .dashboard-grid {
    grid-template-columns: 1fr;
  }

  .metric-card {
    text-align: center;
  }

  .metric-progress {
    position: static;
    margin-top: 15px;
    display: flex;
    justify-content: center;
  }
}
/* Print-Friendly Styles */
@media print {
  body {
    background: white !important;
    color: black !important;
  }

  .app {
    background: white !important;
  }

  /* Header'ı gizle */
  .header, header {
    display: none !important;
  }

  /* Dashboard kartlarını print için optimize et */
  .metric-card {
    background: white !important;
    border: 1px solid #ccc !important;
    color: black !important;
    break-inside: avoid;
  }

  /* Fikir kartları */
  .idea-card {
    background: white !important;
    border: 1px solid #ccc !important;
    color: black !important;
    break-inside: avoid;
    margin-bottom: 20px;
  }

  /* Charts bölümü */
  .charts-section {
    background: white !important;
    color: black !important;
  }
}                
